<script lang="ts">
 import {adminClinicsApi} from '#lib/api/admin/clinics.ts';import {apiMessage} from '#lib/admin/scheduling.ts';import {Button} from '#lib/components/ui/button/index.ts';import type {ApiStaff} from '#lib/types/clinic.ts';import Feedback from './Feedback.svelte';import Modal from './Modal.svelte';import StaffEditor from './StaffEditor.svelte';import StaffTools from './StaffTools.svelte';
 let {facilityId}:{facilityId:string}=$props();let rows=$state<ApiStaff[]>([]),loading=$state(true),error=$state(''),message=$state(''),revision=$state(0),role=$state(''),editor=$state(false),selected=$state<ApiStaff|null>(null),tool=$state<'services'|'leaves'|null>(null),remove=$state(false),busy=$state(false);
 const roles:Record<string,string>={doctor:'醫師',nurse:'護理師',receptionist:'櫃檯',admin:'行政',beautician:'美容師',therapist:'治療師'};
 $effect(()=>{const id=facilityId,r=revision;void r;let live=true;loading=true;error='';adminClinicsApi.staff.list(id).then(v=>{if(live)rows=v;}).catch(e=>{if(live)error=apiMessage(e,'無法載入人員');}).finally(()=>{if(live)loading=false;});return()=>{live=false;};});
 async function deleteStaff(){if(!selected)return;busy=true;error='';try{await adminClinicsApi.staff.delete(facilityId,selected.id);remove=false;revision++;message='人員已刪除';}catch(e){error=apiMessage(e,'人員刪除失敗');}finally{busy=false;}}
</script>
<div class="space-y-4"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="font-semibold">人員列表</h2><div class="flex gap-2"><select aria-label="篩選人員角色" bind:value={role} class="rounded-lg border bg-background px-3"><option value="">全部角色</option>{#each Object.entries(roles) as [key,label] (key)}<option value={key}>{label}</option>{/each}</select><Button onclick={()=>{selected=null;editor=true;}}>新增人員</Button></div></div><Feedback {error} {message}/>{#if error}<Button variant="outline" onclick={()=>revision++}>重試人員列表</Button>{/if}{#if loading}<p role="status">載入人員中…</p>{:else if !error}<div class="grid gap-4 lg:grid-cols-2">{#each rows.filter(p=>!role||p.role===role) as p (p.id)}<article class="space-y-4 rounded-2xl border bg-card p-5"><div class="flex items-center gap-3">{#if p.avatar_url}<img src={p.avatar_url} alt={p.name} class="size-14 rounded-xl object-cover"/>{:else}<span class="grid size-14 place-items-center rounded-xl bg-primary/10 text-xl text-primary">{p.name.slice(0,1)}</span>{/if}<div><h3 class="font-semibold">{p.name}</h3><p class="text-sm text-muted-foreground">{roles[p.role]} · {p.is_active?'啟用':'停用'} · {p.is_bookable?'可預約':'暫停預約'}</p></div></div><p class="text-sm text-muted-foreground">{p.phone||'電話未填'} · {p.email||'信箱未填'} · {p.is_public_visible?'公開顯示':'不公開'}</p><div class="flex flex-wrap gap-2"><Button variant="outline" size="sm" onclick={()=>{selected=p;editor=true;}}>檔案與編輯</Button>{#if ['doctor','beautician','therapist'].includes(p.role)}<Button variant="outline" size="sm" onclick={()=>{selected=p;tool='services';}}>服務對應</Button><Button variant="outline" size="sm" onclick={()=>{selected=p;tool='leaves';}}>休假管理</Button>{/if}<Button variant="ghost" size="sm" onclick={()=>{error='';selected=p;remove=true;}}>刪除人員</Button></div></article>{:else}<p class="rounded-xl border p-8 text-muted-foreground">尚無符合的人員。</p>{/each}</div>{/if}</div>
{#if editor}<StaffEditor bind:open={editor} {facilityId} staff={selected} onSaved={()=>{revision++;message='人員資料已更新';}}/>{/if}
{#if tool&&selected}{#key tool+selected.id}<StaffTools open={true} onClose={()=>tool=null} mode={tool} staff={selected} {facilityId}/>{/key}{/if}
<Modal bind:open={remove} title="刪除人員" description={'確認刪除「'+(selected?.name??'')+'」？此操作無法復原。'} {busy}><Feedback {error}/><div class="mt-4 flex justify-end gap-2"><Button variant="outline" disabled={busy} onclick={()=>remove=false}>取消</Button><Button variant="destructive" disabled={busy} onclick={deleteStaff}>確認刪除</Button></div></Modal>
